data.query:
query Query($where: SalesOrderWhereInput, $whereLines: SalesOrderLineWhereInput) {
  salesOrder(where: $where first: 1) {
    edges {
      node {
        id
        number
        facilityId
        lines(where: $whereLines) {
      edges {
          node {
            id productId quantity {value unitId}
          }
        }
    }

      }
    }
  }
}

data.variablesTransform:
(
$sh := $.sh;
{
  "payload": $state.context.LOCAL.salesOrder.lines.edges.node.{
    "create":{
      "shipmentId": $sh.id,
      "salesOrderLineId": id,
      "stagedQuantity": {
        "value": 0,
        "unitId": quantity.unitId
      },
      "loadedQuantity": {
        "value": 0,
        "unitId": quantity.unitId
      },
            "quantity": {
                "value": quantity.value,
        "unitId": quantity.unitId
            },

      "shippedQuantity":  {
        "value": 0,
        "unitId": quantity.unitId
      },
      "shipmentLineStageId": "New",
      "productId": productId
    }
  }
}

)

