query Query($where: SupplierReturnWhereInput, $orderBy: [SupplierReturnOrderByInput!], $first: Int, $after: String, $whereLines: SupplierReturnLineWhereInput) {
  supplierReturn(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        supplierId
        location{facilityId}
        subsidiaryId
        supplierReturnLines(where: $whereLines) {
          edges {
            node {
              id
              quantity {
                value
                unitId
              }
              productId
            }
          }
        }
      }
    }
  }
}

data.variablesTransform:
(

$s := supplierReturn.edges.node;
$id := $cuid();
{
  "payload": {
    "create": {
    "id":$id,
      "supplierReturnId": $s.id,
      "shipmentTypeId": "Customer Shipment",
      "shipmentStageId": "Open",
      "scheduledShipAt": $moment(),
      "subsidiaryId":$s.subsidiaryId,
      "shipFromFacilityId": $s.location.facilityId,
      "shipToCustomerAddressId": $s.customerAddressShipToId
    }
  },

  "payloadL": $s.supplierReturnLines.edges.node.{
    "create":{
      "shipmentId": $id,
      "supplierReturnLineId": id,
      "stagedQuantity": {
        "value": 0,
        "unitId": quantity.unitId
      },
      "loadedQuantity": {
        "value": 0,
        "unitId": quantity.unitId
      },
      "shipQuantity": quantity,
      "shipmentLineStageId": "New",
      "productId": productId
    }
  }
}

)

(

$s := transferOrder.edges.node;
$id := $cuid();
{
  "payload": {
    "create": {
    "id":$id,
      "transferOrderId": $s.id,
      "shipmentTypeId": "Transfer Shipment",
      "shipmentStageId": "New",
      "scheduledShipAt": $moment(),
      "shipFromFacilityId": $s.fromFacilityId,
      "shipToFacilityId": $s.toFacilityId,
      "shippingLocationId": $state.context.REQUEST.form.shippingLocationId
    }
  },

  "payloadL": $s.lines.edges.node.{
    "create":{
      "shipmentId": $id,
      "transferOrderLineId": id,
      "quantity": {"value":transferQuantity.value, "unitId":transferQuantity.unitId},
      "stagedQuantity": {
        "value": 0,
        "unitId": transferQuantity.unitId
      },
      "loadedQuantity": {
        "value": 0,
        "unitId": transferQuantity.unitId
      },
      "shippedQuantity": {"value":0, "unitId":transferQuantity.unitId},
      "shipmentLineStageId": "New",
      "productId": productId
    }
  }
}

)

